#include <stdio.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int adj[20] = {0};

    for (int i = 0; i < M; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        x--;
        y--;
        adj[x] |= (1 << y);
        adj[y] |= (1 << x);
    }

    int total = 1 << N;
    int answer = 0;

    for (int mask = 1; mask < total; mask++) {
        int ok = 1;
        int m = mask;

        while (m) {
            int v = __builtin_ctz(m);
            if (adj[v] & mask) {
                ok = 0;
                break;
            }
            m &= m - 1;
        }

        if (ok) answer++;
    }

    printf("%d\n", answer);
    return 0;
}
